using System; using System.IO; using UnityEngine; using SkyIsland;
public static class SurvivalReview {
 public static void Validate(){int n=0;Action<bool,string> test=(ok,name)=>{if(!ok)throw new Exception("SURVIVAL FAIL "+name);n++;};var island=new HexIsland();var inv=new SurvivalInventory(island,new SurvivalState());test(island.Wood==0&&island.Stone==0,"fresh empty inventory");test(inv.HarvestAmount("wood")==1,"punch wood");test(inv.HarvestAmount("stone")==0,"hand cannot mine");test(!inv.Craft("bench",new Hex(0,0),out _)&&island.Wood==0,"failed craft no debit");inv.Collect("wood",6);test(inv.Craft("bench",new Hex(0,0),out _)&&island.Wood==0,"bench craft");test(!inv.PlaceBench(new Hex(0,0),out _)&&inv.State.benches==1,"core protected");test(inv.PlaceBench(new Hex(0,1),out _)&&inv.State.benches==0,"place bench");inv.Collect("wood",7);test(inv.Craft("axe",new Hex(0,0),out _),"craft axe");inv.State.selectedSlot=1;test(inv.HarvestAmount("wood")==3,"axe output");test(inv.Craft("pickaxe",new Hex(0,0),out _),"craft pick");inv.State.selectedSlot=2;test(inv.HarvestAmount("stone")==2,"pick output");inv.Collect("food",1);test(inv.State.food==1,"pet food persists");var save=island.Snapshot(Vector3.zero);save.survival=inv.State;var restored=JsonUtility.FromJson<IslandSave>(JsonUtility.ToJson(save));test(restored.survival.food==1&&restored.survival.axes==1,"survival save roundtrip");test(new SurvivalInventory(island,new SurvivalState{food=-1}).State.food==0,"invalid inventory reset");Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/survival-tests.txt","PASS "+n+" assertions; inventory/crafting/save only; pet movement and mouse input require playtest. UTC "+DateTime.UtcNow.ToString("o"));Debug.Log("SKY_SURVIVAL_TESTS_PASS "+n);}
}
